const files = new Map();
for (const [path, before, after] of edits) {
  const source = files.get(path) ?? fs.readFileSync(path, 'utf8');
  if (source.split(before).length !== 2) throw new Error(`Expected one unchanged anchor: ${path}`);
  files.set(path, source.replace(before, after));
}
for (const [path, source] of files) fs.writeFileSync(path, source);
console.log(`Applied fixed web-authored edits to ${files.size} files.`);
